package io.spring.application;

import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import io.spring.application.data.CommentData;
import io.spring.application.data.ProfileData;
import io.spring.core.user.User;
import io.spring.infrastructure.mybatis.readservice.CommentReadService;
import io.spring.infrastructure.mybatis.readservice.UserRelationshipQueryService;
import java.util.Collections;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class CommentQueryServiceTest {

  @org.mockito.Mock private CommentReadService commentReadService;
  @org.mockito.Mock private UserRelationshipQueryService userRelationshipQueryService;

  // GreyTest trace: findByArticleId | condition false for null user or empty comments | BR-037 -> TP-015 -> TC-077
  @Test
  void findByArticleId_skipsFollowingLookupForNullUserOrEmptyComments() {
    CommentQueryService sut = new CommentQueryService(commentReadService, userRelationshipQueryService);
    User user = new User("reader@example.com", "reader", "password", null, null);
    ProfileData profile = new ProfileData();
    profile.setId("author-1");
    CommentData comment = new CommentData();
    comment.setId("comment-1");
    comment.setProfileData(profile);
    when(commentReadService.findByArticleId("article-1")).thenReturn(Collections.singletonList(comment));
    when(commentReadService.findByArticleId("article-2")).thenReturn(Collections.<CommentData>emptyList());

    assertTrue(sut.findByArticleId("article-1", null).size() == 1);
    assertTrue(sut.findByArticleId("article-2", user).isEmpty());

    verify(commentReadService).findByArticleId("article-1");
    verify(commentReadService).findByArticleId("article-2");
    verify(userRelationshipQueryService).toString();
  }
}
